sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 anchor;
uniform float shearX;
uniform float shearY;
uniform float rotation;
uniform float scaleX;
uniform float scaleY;
uniform float transparentEdge;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 anc = anchor * size;
    float2 q = coord - anc;
    q.x -= q.y * shearX;
    q.y -= q.x * shearY;
    q = rot2(q, -radians(rotation)) / float2(scaleX, scaleY);
    float2 p = anc + q;
    float4 r = transparentEdge > 0.5 ? texT(p) : tex(p);
    return fin(c, r, opacity);
}
